-- Authorized example content only. Run in the Supabase SQL editor as project owner.
-- Idempotent: existing example IDs are preserved, including user edits.
begin;
do $seed$
declare owner_id uuid; item jsonb; step jsonb; index integer;
begin
 perform pg_advisory_xact_lock(hashtextextended('studio-five-english-examples-20261104',0));
 select p.id into owner_id from public.profiles p join auth.users u on u.id=p.id
 where p.is_superadmin is true and u.email='ml5571@columbia.edu';
 if owner_id is null then raise exception 'Existing superadmin profile was not found'; end if;
 for item in select value from jsonb_array_elements($examples$[{"id": "1ab5e8cb-b575-56b0-a8ee-c1f625b025c1", "name": "Example 1: Office Cat Captions", "description": "Upload a cat photo to turn a workday mood into five funny captions. Try this input: Monday morning, three meetings, and no coffee.", "steps": [{"name": "Observe the cat", "prompt": "Describe only the visible cat, pose, expression, objects, and setting in the uploaded image. Do not invent details or write captions. If no image is provided, describe the scene from this input instead: {{input}}", "use_image": true}, {"name": "Connect the workplace joke", "prompt": "Turn this description into one specific, relatable workplace joke. Keep it playful and kind. Return only the observation. Description: {{previous}}", "use_image": false}, {"name": "Write five office captions", "prompt": "Write five distinct funny captions based on this observation. Use a numbered list, at most 12 words per caption, and no introduction. Observation: {{previous}}", "use_image": false}]}, {"id": "257e5978-2a58-5107-8169-7126b1b355be", "name": "Example 2: Everyday Rant to Meme", "description": "Turn a harmless everyday annoyance into five shareable meme captions. Try this input: My food delivery arrived after I had already cooked dinner.", "steps": [{"name": "Find the comic tension", "prompt": "Identify the expectation, the reality, and the small frustration in this everyday rant. Keep the facts from the input and avoid inventing personal details. Input: {{input}}", "use_image": false}, {"name": "Build a funny analogy", "prompt": "Create one surprising, relatable analogy for the situation below. Keep it lighthearted and avoid targeting real people. Return only the analogy. Situation: {{previous}}", "use_image": false}, {"name": "Create five meme lines", "prompt": "Write five short meme captions inspired by this analogy. Use a numbered list, at most 12 words each. Avoid repeating the same punchline. Analogy: {{previous}}", "use_image": false}]}, {"id": "b0ecd5b2-7958-56b9-86fd-cec82012293f", "name": "Example 3: Pet Photo to Mini Story", "description": "Give a pet an imaginary inner monologue and a tiny comic adventure. Upload a pet photo. Try this input: This pet has just been promoted to household manager.", "steps": [{"name": "Describe the pet scene", "prompt": "Describe the visible pet, its pose, and its surroundings. Separate visible observations from uncertainty. Do not infer breed or personality as fact. If there is no image, use this scene: {{input}}", "use_image": true}, {"name": "Imagine a tiny adventure", "prompt": "Using this visual description, invent a clearly fictional, wholesome three-sentence adventure in which the pet takes an everyday household task far too seriously. Description: {{previous}}", "use_image": false}, {"name": "Write the pet story card", "prompt": "Turn this fictional adventure into a funny title and a first-person pet monologue of 60-90 words. Include a beginning, a small mishap, and a gentle punchline. Return only the title and monologue. Adventure: {{previous}}", "use_image": false}]}, {"id": "c174cec6-20da-5450-b9af-473b6beb0117", "name": "Example 4: Product Photo to Playful Ad", "description": "Turn a product image or description into five playful advertising lines. Upload an optional product photo. Try this input: A reusable coffee mug for people who always forget their coffee.", "steps": [{"name": "Extract grounded product details", "prompt": "List only product details visible in the uploaded image or explicitly stated in the input. Do not invent specifications, prices, certifications, or performance claims. If there is no image, rely on the input. Input: {{input}}", "use_image": true}, {"name": "Choose an amusing angle", "prompt": "Using these grounded details, identify one everyday customer frustration and a playful advertising angle. Distinguish a creative idea from a factual product claim. Details: {{previous}}", "use_image": false}, {"name": "Write five ad captions", "prompt": "Write five distinct, humorous ad captions using this angle. Keep each under 15 words. Do not invent guarantees, specifications, prices, or endorsements. Return a numbered list only. Angle: {{previous}}", "use_image": false}]}, {"id": "fa8b3f48-12b7-5fe6-953c-32831e27995d", "name": "Example 5: Study Topic to Funny Mnemonic", "description": "Turn a study concept into a memorable joke and accurate mnemonic. Try this input: Explain precision versus recall in machine learning.", "steps": [{"name": "Explain the study concept", "prompt": "Explain the study topic accurately in plain English in no more than 120 words. Define key terms and preserve important distinctions. If the input is unclear, state a reasonable interpretation. Topic: {{input}}", "use_image": false}, {"name": "Create a memorable analogy", "prompt": "Create a funny everyday analogy for this explanation. Map each part of the analogy to the concept and state one limitation so the joke does not become a misconception. Explanation: {{previous}}", "use_image": false}, {"name": "Make a study reminder card", "prompt": "Using this analogy, write a short title, a one-sentence mnemonic, two accurate takeaway bullets, and one quick self-check question with its answer. Keep the whole card under 140 words. Analogy: {{previous}}", "use_image": false}]}]$examples$::jsonb) loop
  if exists(select 1 from public.studio_chains where id=(item->>'id')::uuid) then continue; end if;
  insert into public.studio_chains(id,name,description,created_by)
  values((item->>'id')::uuid,item->>'name',item->>'description',owner_id);
  index:=0;
  for step in select value from jsonb_array_elements(item->'steps') loop
   index:=index+1;
   insert into public.studio_steps(chain_id,position,name,prompt,use_image)
   values((item->>'id')::uuid,index,step->>'name',step->>'prompt',(step->>'use_image')::boolean);
  end loop;
  perform public.studio_validate_steps((item->>'id')::uuid);
 end loop;
end $seed$;
commit;
select c.id,c.name,count(s.id) as steps from public.studio_chains c
join public.studio_steps s on s.chain_id=c.id
where c.id in ('1ab5e8cb-b575-56b0-a8ee-c1f625b025c1'::uuid,'257e5978-2a58-5107-8169-7126b1b355be'::uuid,'b0ecd5b2-7958-56b9-86fd-cec82012293f'::uuid,'c174cec6-20da-5450-b9af-473b6beb0117'::uuid,'fa8b3f48-12b7-5fe6-953c-32831e27995d'::uuid)
group by c.id,c.name order by c.name;
